/** Workspace-first roundtrip review of both unchanged provider converters. */
import * as fs from 'node:fs/promises';
import * as path from 'node:path';
import * as url from 'node:url';
import * as module from 'node:module';
import * as assert from 'node:assert/strict';

const directory = path.dirname(url.fileURLToPath(import.meta.url));
const repository = path.resolve(directory, '../../..');
const workspace = process.env.WORKSPACE_UI_SOURCE_DIR ?? path.resolve(repository, '../workspace_ui');
const requireUi = module.createRequire(path.join(workspace, 'package.json'));
const { JSDOM, VirtualConsole } = requireUi('jsdom');
const data = JSON.parse(await fs.readFile(path.join(directory, 'telegram_message_types_review.json'), 'utf8'));
const escape = value => String(value).replace(/[&<>"']/g, character => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[character]));
const captured = JSON.parse(await fs.readFile(process.env.REVIEW_RENDER_OUTPUT, 'utf8'));
const rendered = new Map(captured.cases.map(row=>[row.id,row]));
const categories = {quotes:'Цитаты',formatting:'Текст и форматирование',mentions:'Упоминания',media:'Файлы и медиа',links:'Ссылки',special:'Специальные типы',runtime:'Чаты и события',native:'Нативный Telegram'};

function telegramBody(value) {
  const text = value.text;
  const entities = [...value.entities].sort((a,b) => a.offset-b.offset || b.length-a.length);
  function render(start,end,values) {
    let output = '', cursor = start;
    while (values.length) {
      const [entity,...rest] = values;
      const right = entity.offset+entity.length;
      if (entity.offset < cursor || right > end) { values=rest;continue; }
      output += escape(text.slice(cursor,entity.offset));
      let body = render(entity.offset,right,rest.filter(item => item.offset < right));
      const tags={MessageEntityBold:'strong',MessageEntityItalic:'em',MessageEntityStrike:'del',MessageEntityUnderline:'u',MessageEntityCode:'code',MessageEntityPre:'pre',MessageEntityBlockquote:'blockquote'};
      if (tags[entity.type]) body=`<${tags[entity.type]}>${body}</${tags[entity.type]}>`;
      if (entity.type==='MessageEntitySpoiler') body=`<span class="telegram-spoiler" tabindex="0" title="Спойлер: фокус или наведение раскрывает текст">${body}</span>`;
      if (entity.type==='MessageEntityTextUrl') body=`<a href="${escape(/^(https?:|mailto:|tg:)/.test(entity.url) ? entity.url : '#')}">${body}</a>`;
      output += body;cursor=right;values=rest.filter(item=>item.offset>=right);
    }
    return output+escape(text.slice(cursor,end));
  }
  return `<div class="telegram-text">${render(0,text.length,entities)}</div>`;
}

function semanticText(node, depth=0) {
  if (node.nodeType===3) return node.textContent;
  if (node.nodeType!==1) return '';
  if (node.matches('[data-workspace-quote]')) {
    const [header,body]=node.children;
    const inside=semanticText(body).trim().split('\n').map(line=>'│ '+line).join('\n');
    return `\n┌ ${header.textContent.trim()}\n${inside}\n└\n`;
  }
  if (node.classList.contains('fixture-time')) return '';
  const content=[...node.childNodes].map(child=>semanticText(child,depth)).join('');
  if (node.tagName==='BR') return '\n';
  if (node.tagName==='LI') return '• '+content+'\n';
  if (['P','DIV','PRE','H1','H2','H3','UL','OL'].includes(node.tagName)) return content+'\n';
  return content;
}

const priority=['nested_message_quote','triple_nested_quote','multiple_commented_quotes','reply_to_multiple_commented_quotes','partial_multiple_commented_quotes','partial_nested_direct_context_quote','nested_direct_context_quote'];
const rows=[...data.zulip_cases,...data.native_telegram_cases].sort((a,b)=>{
 const ai=priority.indexOf(a.example.name),bi=priority.indexOf(b.example.name);
 return (ai<0?999:ai)-(bi<0?999:bi);
});
assert.equal(rows.length,96);
const idFor=row=>(row.fixture_source==='telegram'?'native-':'')+row.example.name;
assert.equal(new Set(rows.map(idFor)).size,96);
const nativeBody=html=>`<div class="workspace-native"><div class="fixture-bubble">${html}</div></div>`;
function flags(cycle) {
 return `<div class="cycle-flags"><span class="badge ${cycle.exact_roundtrip?'supported':'attention'}">Markdown ${cycle.exact_roundtrip?'совпал':'изменился'}</span><span class="badge ${cycle.repeat_stable?'':'attention'}">Второй цикл ${cycle.repeat_stable?'не меняет результат':'ещё меняет результат'}</span><span class="badge">Семантика: на ревью</span></div>`;
}
const cards=rows.map((row,index)=>{
 const e=row.example,id=idFor(row),view=rendered.get(id);
 assert.ok(view,id);
 const notes=[...row.notes];
 if (!row.telegram.repeat_stable) notes.push('Текст после второго цикла Telegram отличается от первого. Это повторяемое изменение текущего конвертера; сравните Markdown ниже.');
 const issue=notes.length>0;
 const proposed=row.category==='quotes'?semanticText(new JSDOM(`<div>${view.workspace}</div>`, {virtualConsole:new VirtualConsole()}).window.document.body.firstElementChild).replace(/\n{3,}/g,'\n\n').trim():null;
 const refs=Object.keys(row.telegram.references).length>0;
 return `<article class="example" id="${escape(id)}" data-category="${row.category}" data-review="${issue}" data-diff="${!row.telegram.exact_roundtrip||!row.zulip.exact_roundtrip}" data-search="${escape((e.name+' '+e.description+' '+categories[row.category]+' '+row.telegram.text).toLowerCase())}">
 <header class="example-heading"><div><span class="case-number">${String(index+1).padStart(2,'0')}</span><a href="#${escape(id)}">${escape(e.name.replaceAll('_',' '))}</a></div><span class="badge">${escape(categories[row.category])}</span></header><p class="description">${escape(e.description)}</p>
 <h3 class="cycle-title">Workspace → Zulip → Workspace</h3>${flags(row.zulip)}
 <div class="comparison roundtrip-zulip"><section class="column workspace canonical"><h3>1. Workspace <small>Каноническое исходное сообщение</small></h3>${nativeBody(view.workspace)}</section><section class="column zulip"><h3>2. Zulip <small>Результат текущей исходящей конвертации</small></h3><div class="message-body rendered_markdown">${view.zulip}</div></section><section class="column workspace returned"><h3>3. Workspace <small>После обратной конвертации</small></h3>${nativeBody(view.zulipReturned)}</section></div>
 <details class="cycle-data"><summary>Точный Markdown: исходный → Zulip → обратно → повторно</summary><div class="raw-grid"><section><h4>Исходный Workspace</h4><pre>${escape(e.expected_payload.content)}</pre></section><section><h4>Zulip</h4><pre>${escape(row.zulip.content)}</pre></section><section><h4>Workspace после первого цикла</h4><pre>${escape(row.zulip.returned.content)}</pre></section><section><h4>Workspace после второго цикла</h4><pre>${escape(row.zulip.second.returned.content)}</pre></section></div></details>
 <h3 class="cycle-title">Workspace → Telegram → Workspace</h3>${flags(row.telegram)}
 <div class="comparison roundtrip-telegram"><section class="column workspace canonical"><h3>1. Workspace <small>То же каноническое сообщение</small></h3>${nativeBody(view.workspace)}</section><section class="column telegram"><h3>2. Telegram <small>Текст и entities текущего конвертера</small></h3><div class="telegram-bubble">${telegramBody(row.telegram)}</div>${refs?'<div class="reference-note">Есть reply / файл / упоминание в references. Их разрешение и доставка здесь не выполняются.</div>':''}</section><section class="column workspace returned"><h3>3. Workspace <small>Возвращённые текст и entities</small></h3>${nativeBody(view.telegramReturned)}<div class="reference-note">Текстовый цикл. Полный мост дополнительно восстанавливает reply, файлы и личности; его итог здесь не имитируется.</div></section></div>
 <details class="cycle-data"><summary>Точный Markdown: исходный → Telegram → обратно → повторно; entities и references</summary><div class="raw-grid"><section><h4>Исходный Workspace</h4><pre>${escape(e.expected_payload.content)}</pre></section><section><h4>Telegram: текст / entities / references</h4><pre>${escape(JSON.stringify({text:row.telegram.text,entities:row.telegram.entities,references:row.telegram.references},null,2))}</pre></section><section><h4>Workspace после первого цикла</h4><pre>${escape(row.telegram.roundtrip)}</pre></section><section><h4>Workspace после второго цикла</h4><pre>${escape(row.telegram.second.roundtrip)}</pre></section></div></details>
 ${notes.length?`<div class="observed"><strong>Наблюдаемое сейчас</strong>${notes.map(note=>`<p>${escape(note)}</p>`).join('')}</div>`:''}
 <div class="proposal"><strong>Предложение для ревью — ещё не реализовано</strong><p>${escape(row.proposal)}</p>${proposed?`<details class="proposal-text"><summary>Предлагаемое сохранение вложенности и авторства цитат</summary><pre>${escape(proposed)}</pre></details>`:''}</div>
 <details class="fixture-data"><summary>Происхождение примера и полный захват обоих конвертеров</summary><p>Источник тестового случая: ${row.fixture_source==='zulip'?'каталог Zulip':'нативный Telegram'}. Эталон для обоих циклов — payload Workspace.</p><pre>${escape(JSON.stringify(row,null,2))}</pre></details></article>`;
}).join('\n');
const stat=provider=>({exact:rows.filter(r=>r[provider].exact_roundtrip).length,stable:rows.filter(r=>r[provider].repeat_stable).length});
const z=stat('zulip'),t=stat('telegram');
const attentionCount=rows.filter(row=>row.notes.length||!row.telegram.repeat_stable).length;
const quoteCount=rows.filter(row=>row.category==='quotes').length;
const html=`<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="referrer" content="no-referrer"><title>Workspace: обратимая конвертация сообщений</title><style>${captured.styles}
.page-header,.toolbar-inner,.container{max-width:1760px}.comparison{grid-template-columns:repeat(3,minmax(0,1fr))}.telegram .telegram-bubble{margin:12px 0 20px}.telegram-text{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.65;min-height:24px}.telegram-bubble{padding:14px 16px;background:#e6f3e1;border:1px solid #d4e6cf;border-radius:13px;overflow-wrap:anywhere}.telegram-text pre{white-space:pre-wrap;margin:8px 0;background:#d5e7d1;padding:10px;border-radius:7px}.telegram-text code{font-size:12px}.telegram-text blockquote{border-left:3px solid #66a765;margin:8px 0;padding:8px 12px}.telegram-spoiler{background:#526255;color:#526255;border-radius:3px;cursor:pointer}.telegram-spoiler:hover,.telegram-spoiler:focus{background:#c4ddbf;color:inherit}.status-banner{margin:18px 0 0;border-left:4px solid #d1902e;background:#fff6e7;border-radius:5px;padding:14px 18px;font-size:13px;line-height:1.65}.status-banner strong{display:block}.quick-links{display:flex;gap:9px;flex-wrap:wrap;margin-top:18px}.quick-links a{font-size:12px;border:1px solid #d4dfe9;padding:7px 11px;border-radius:7px;background:white}.observed,.proposal{padding:15px 22px;border-top:1px solid #e5e8ed;font-size:12px;line-height:1.6}.observed{background:#fff0ec;color:#793e30}.proposal{background:#f1f6fd;color:#3c526c}.observed p,.proposal p{margin:5px 0 0}.proposal pre,.cycle-data pre{font:12px/1.7 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;background:#fff;padding:15px;border-radius:7px;color:#2e4055}.proposal-text{margin-top:10px}.badge.attention{color:#9a4936;background:#fff0eb}.reference-note{font-size:11px;line-height:1.6;background:#f2f4f8;padding:9px;border-radius:5px;margin-top:12px}.category-select{border:1px solid #ccd6e2;border-radius:7px;padding:9px;background:white;max-width:240px}.legend{font-size:12px;color:#62748a;max-width:1150px;margin-top:12px}.count{font-size:11px}.source-section{font-size:21px;scroll-margin-top:100px;margin:30px 0 18px}.column h3 small{font-size:10px}.footer{line-height:1.8}.telegram-text:empty:after{content:'Текст отсутствует; проверьте references и runtime-путь медиа/ответа';color:#6a796c;font-size:11px}.intro{max-width:1120px}.toolbar-inner{flex-wrap:wrap;gap:12px}.search{max-width:460px}.cycle-title{padding:15px 22px 4px;font-size:15px;font-weight:700;background:#f6f8fb;border-top:1px solid #e4e8ed}.cycle-flags{display:flex;gap:8px;flex-wrap:wrap;padding:5px 22px 12px;background:#f6f8fb}.cycle-data{margin:0;padding:12px 22px;border-top:1px solid #e4e8ed;font-size:12px}.raw-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.raw-grid>section{min-width:0}.raw-grid h4{font-size:12px;margin-top:10px}.contract{margin-top:28px;padding:24px;background:white;border:1px solid #d8e3ee;border-radius:12px;font-size:13px;line-height:1.75;scroll-margin-top:100px}.contract h2{font-size:21px;font-weight:700}.contract h3{font-size:15px;font-weight:700;margin-top:18px}.contract ol{list-style:decimal;padding-left:22px}.contract li{margin:8px 0}.contract table{width:100%;border-collapse:collapse;margin-top:14px;font-size:12px}.contract th,.contract td{padding:12px;border:1px solid #e0e6ee;text-align:left;vertical-align:top}.contract th{background:#eef3f8}.metrics{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.metric{background:#f0f4fa;border-radius:8px;padding:15px}.metric b{display:block;font-size:17px}.metric small{display:block;line-height:1.7}.workspace-native{margin:0;height:auto;min-height:0;width:auto;background:transparent}.column .message-body{margin:0}.column details{margin-left:0}
@media(max-width:1100px){.comparison{grid-template-columns:1fr}.column+.column{border-left:0;border-top:1px solid #e4e8ed}.workspace-native{margin-left:0}.zulip .message-body{margin-left:0}.column details{margin-left:0}.category-select{flex:1}}
@media(max-width:600px){.raw-grid,.metrics{grid-template-columns:1fr}.contract{padding:16px}.contract table{display:block;overflow:auto}.cycle-flags{padding-left:14px}.cycle-title{padding-left:14px}}
@media print{.comparison{grid-template-columns:1fr}.example{break-inside:auto}}
</style></head><body><header class="page-header"><div class="eyebrow">WORKSPACE · REVIEW BEFORE IMPLEMENTATION · 01.11.2026</div><h1>Сообщение должно вернуться в Workspace</h1><p class="intro">Workspace — каноническое сообщение. Для каждого из 96 примеров показаны оба цикла: <strong>Workspace → Zulip → Workspace</strong> и <strong>Workspace → Telegram → Workspace</strong>. 79 случаев взяты из каталога Zulip, 17 — из Telegram; происхождение примера не определяет формат Workspace.</p><div class="status-banner"><strong>Стабильность — сохранение смысла при отправке и возврате</strong>Не только читаемое сообщение снаружи: после возврата должны сохраниться текст, форматирование, уровни и авторы цитат, ссылки, упоминания и вложения. Повторный цикл не должен продолжать менять сообщение. Ниже показано текущее поведение неизменённых конвертеров; предложения требуют ревью.</div><div class="metrics"><div class="metric"><b>Zulip: ${z.exact}/96</b><small>Точное совпадение Markdown после первого цикла с синтетическими данными связи.<br>Второй цикл стабилен: ${z.stable}/96. Это проверка конвертеров, не доставки.</small></div><div class="metric"><b>Telegram: ${t.exact}/96</b><small>Точное совпадение Markdown в текстовом цикле без runtime-восстановления reply, файлов и личностей.<br>Второй цикл стабилен: ${t.stable}/96. Числа нельзя сравнивать с Zulip как общий процент готовности.</small></div></div><p class="legend">Совпадение Markdown — дополнительная строгая проверка. Разные записи могут быть равны по смыслу; одинаковый Markdown не подтверждает отправку файла. Внешний вид Workspace и Zulip построен локальными рендерами клиентов. Telegram — иллюстрация text/entities, а не скриншот клиента. Все данные синтетические; страница не обращается к API.</p><nav class="quick-links"><a href="#contract">Правила обратимости для ревью</a><a href="#nested_message_quote">Двойная цитата</a><a href="#triple_nested_quote">Тройная цитата</a><a href="#multiple_commented_quotes">Несколько цитат</a><a href="#partial_multiple_commented_quotes">Частичные цитаты</a><a href="#native-nested_unicode">Unicode и вложенный стиль</a></nav>
<section class="contract" id="contract"><h2>Предлагаемый контракт конвертации</h2><ol><li><strong>Эталон хранится в Workspace.</strong> Конвертация сохраняет семантическую структуру сообщения: текст и его порядок, типы блоков, оформление, цитаты с автором и вложенностью, адреса ссылок, личности и файлы. Конкретная запись Markdown может нормализоваться.</li><li><strong>Сначала нативные возможности сервиса.</strong> Поддерживаемые стили, ссылки, файлы и одна reply-связь передаются штатно. Для структуры без аналога нужен читаемый вариант представления, сохраняющий смысл. Для вложенных цитат — все авторы, тексты, уровни и комментарии в исходном порядке.</li><li><strong>Возврат своего неизменённого сообщения.</strong> По существующей связи внешнего сообщения с Workspace можно восстановить каноническую структуру, которую внешний формат не хранит. Восстановление допустимо только для той же версии: совпадают текст/entities, reply и состав медиа. Оно не должно затереть внешнее редактирование.</li><li><strong>Новое или изменённое сообщение извне.</strong> Разбирается фактическое содержимое сервиса. Нельзя восстанавливать старую версию поверх правок или угадывать скрытую структуру по произвольным похожим маркерам. Если необходимой информации нет ни в формате, ни в связи с оригиналом, полное восстановление невозможно — это ограничение должно быть явным.</li><li><strong>Проверяется полный цикл и повтор.</strong> Для каждого типа — Workspace → сервис → Workspace, затем ещё раз. Сравниваются семантические данные, а не только скриншот или строка Markdown. Отдельно проверяются сообщение, впервые созданное в сервисе, внешнее редактирование, отправка/получение медиа и отсутствие дублей.</li></ol>
<table><thead><tr><th>Тип</th><th>Что обязательно сохраняется при возврате</th><th>Как представлять снаружи — предложение</th></tr></thead><tbody><tr><td>Обычный текст / Unicode / литералы</td><td>Все символы, переносы, значимые пробелы. Литералы не становятся разметкой.</td><td>Текст и штатные стили; код остаётся кодом.</td></tr><tr><td>Вложенные и несколько цитат</td><td>Автор, источник, выделенный фрагмент, уровни и порядок комментариев.</td><td>Нативный ответ плюс полное видимое представление цитат. Telegram не поддерживает вложенные blockquote entities; текстовые уровни — вариант для ревью, а не готовый обратимый кодек.</td></tr><tr><td>Списки / таблицы / заголовки / спойлеры</td><td>Структура, порядок, ячейки, текст и скрываемый диапазон.</td><td>Нативные блоки, где есть; читаемая таблица моноширинным текстом там, где её нет. Структура оригинала сохраняется в Workspace.</td></tr><tr><td>Упоминания / внутренние ссылки</td><td>Личность, адресат сервиса выбранного топика, переход и режим silent.</td><td>Связанный аккаунт нужного сервиса. Если его нет — читаемая подпись без ложного пинга. Общедоступный текст не должен содержать неработающий внутренний URN.</td></tr><tr><td>Файлы / фото / видео / аудио</td><td>Идентичность файла, содержимое, имя, подпись и порядок вложений.</td><td>Нативная загрузка, проверка скачанных байтов и состава альбома. Текстовый снимок конвертера этого не доказывает.</td></tr><tr><td>Функция без общего аналога</td><td>Исходный смысл и данные; честная граница интерактивности.</td><td>Читаемый снимок + сохранённая каноническая структура для неизменённого возврата. Нельзя обещать восстановить отсутствующие данные из нового внешнего текста.</td></tr><tr><td>Правки / реакции / удаление / доставка</td><td>Связь с исходным сообщением и актуальная версия, без эхо-дублей.</td><td>Отдельные события моста; обязательные сквозные тесты в обоих сервисах.</td></tr></tbody></table><h3>Два уровня проверки</h3><p>Эта страница фиксирует преобразования локальных конвертеров и обсуждаемый контракт. При реализации потребуются регрессионные тесты семантического цикла и живая отправка/получение через Zulip и Telegram. Полный мост не заменён текстовой моделью страницы.</p><p>Источник ограничения Telegram: <a href="https://core.telegram.org/bots/api#formatting-options" target="_blank" rel="noopener noreferrer">официальные ограничения форматирования</a>. Изменения конвертеров будут сделаны после согласования этой страницы.</p></section></header>
<div class="toolbar"><div class="toolbar-inner"><label class="sr-only" for="search">Поиск</label><input class="search" id="search" type="search" placeholder="Поиск по типу, названию или тексту…"><label class="sr-only" for="category">Категория</label><select id="category" class="category-select"><option value="all">Все категории</option>${Object.entries(categories).map(([key,label])=>`<option value="${key}">${label}</option>`).join('')}</select><label class="filter"><input id="review-only" type="checkbox"> Замечания</label><label class="filter"><input id="diff-only" type="checkbox"> Markdown изменился</label><output id="count" class="count" aria-live="polite">96 / 96</output></div></div>
<main class="container"><h2 class="source-section">96 канонических примеров Workspace · 192 цикла через сервисы · ${quoteCount} случаев с цитатами</h2>${cards}<p id="empty" class="empty-state" hidden>Нет подходящих примеров.</p></main><footer class="footer">Текущие конвертеры без исправлений · 79/79 случаев zulip_messages.json + 17/17 telegram_messages.json · ${attentionCount} с замечаниями<br>Исходный Workspace, представление сервиса, возвращённый Workspace и точные данные обоих проходов доступны в каждом примере.</footer>
<script>const cards=[...document.querySelectorAll('article.example')];function filter(){const q=document.querySelector('#search').value.toLowerCase().trim(),category=document.querySelector('#category').value,review=document.querySelector('#review-only').checked,diff=document.querySelector('#diff-only').checked;let visible=0;for(const card of cards){card.hidden=!(card.dataset.search.includes(q)&&(category==='all'||category===card.dataset.category)&&(!review||card.dataset.review==='true')&&(!diff||card.dataset.diff==='true'));if(!card.hidden)visible++;}document.querySelector('#count').textContent=visible+' / '+cards.length;document.querySelector('#empty').hidden=visible!==0;}for(const id of ['search','category','review-only','diff-only'])document.getElementById(id).addEventListener(id==='search'?'input':'change',filter);function toggle(header){const block=header.parentElement,open=block.classList.toggle('open');block.classList.toggle('is-open',open);header.setAttribute('aria-expanded',String(open));block.querySelector(':scope > .spoiler-content')?.setAttribute('aria-hidden',String(!open));}document.addEventListener('click',event=>{const h=event.target.closest('.spoiler-header');if(h)toggle(h);});document.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('.spoiler-header')){event.preventDefault();toggle(event.target);}});</script></body></html>`;
const output=path.join(repository,'docs/telegram_message_types_review.html');
const styleEnd=html.indexOf('</style>')+8;
const outputHtml=html.slice(0,styleEnd).replace(/[ \t]+$/gm,'')+html.slice(styleEnd).replace(/[ \t]+$/gm,spaces=>spaces.replaceAll(' ','&#32;').replaceAll('\t','&#9;'));
await fs.writeFile(output,outputHtml);
const checked=new JSDOM(outputHtml,{virtualConsole:new VirtualConsole()});
assert.equal(checked.window.document.querySelectorAll('article.example').length,96);
assert.equal(checked.window.document.querySelectorAll('.comparison').length,192);
assert.equal(checked.window.document.querySelectorAll('.comparison>.column').length,576);
for (const id of priority) assert.ok(checked.window.document.getElementById(id),id);
for(const element of checked.window.document.querySelectorAll('[src]')) assert.match(element.getAttribute('src'),/^data:/);
checked.window.close();
console.log(JSON.stringify({file:output,cases:96,cycles:192,zulip:z,telegram:t,quotes:quoteCount,attention:attentionCount,sizeBytes:Buffer.byteLength(outputHtml)}));
